// fnv1a: the 64-bit FNV-1a hash of 8 MiB of generated bytes (printed as a
// signed 64-bit number, as Mimic's i64 prints it).
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    const int64_t n = 1 << 23;
    uint8_t *data = malloc(n);
    for (int64_t i = 0; i < n; i++) data[i] = (uint8_t)((i * 2654435761LL >> 13) & 255);
    uint64_t h = 0xcbf29ce484222325ull;
    for (int64_t i = 0; i < n; i++) h = (h ^ data[i]) * 0x100000001b3ull;
    printf("%lld\n", (long long)h);
    free(data);
    return 0;
}
